return '\u300e\u5168\u4f53\u300f\u6307\u8be5\u5e01\u79cd\u7684\u806a\u660e\u94b1\u6837\u672c\uff0c'
+ '\u6837\u672c\u91cf\u968f\u5e01\u79cd\u89c4\u6a21\u53d8\u5316\uff08\u5b9e\u6d4b ' + (s.min || 0)
