return '<div class="smx-pf"><div class="smx-pf-head"><b>\u8d26\u6237\u76c8\u5229\u5360\u6bd4\u5bf9\u6bd4\uff08\u5168\u4f53 vs \u5927\u6237\uff09</b>'
